-- ============================================
-- LUMA — Thème 13 : MOYEN 1/3 x4 — Naviguer une soirée networking avec plusieurs interlocuteurs
-- ============================================


update scenarios set content = '{"characters": {"person1": "interlocuteur 1", "person2": "interlocuteur 2", "person3": "interlocuteur 3"}, "start_node": "n1", "nodes": {"n1": {"speaker": "person1", "text": "So, what brings you to this networking event tonight?", "text_fr": "Alors, qu''est-ce qui vous amène à cet événement de networking ce soir ?", "choices": [{"text": "I''m looking to connect with people in sustainable business practices.", "text_fr": "Je cherche à me connecter avec des gens dans les pratiques d''affaires durables.", "next": "n2"}, {"text": "Mostly curiosity, honestly — I''m exploring new career directions.", "text_fr": "Surtout de la curiosité, honnêtement — j''explore de nouvelles directions de carrière.", "next": "n2b"}]}, "n2": {"speaker": "person1", "text": "That''s exactly my field! We should definitely talk more about this.", "text_fr": "C''est exactement mon domaine ! On devrait définitivement en parler plus.", "choices": [{"text": "I''d love that. Let''s exchange info before this event wraps up.", "text_fr": "J''adorerais ça. Échangeons nos infos avant que l''événement se termine.", "next": "n3"}]}, "n2b": {"speaker": "person1", "text": "That''s a big step, exploring new directions. What field are you considering?", "text_fr": "C''est un grand pas, explorer de nouvelles directions. Vous considérez quel domaine ?", "choices": [{"text": "Something in tech, though I''m still figuring out the specifics.", "text_fr": "Quelque chose en tech, même si je détermine encore les spécificités.", "next": "n3"}]}, "n3": {"speaker": "person1", "text": "Well, good luck with that! I see someone I need to catch before they leave — great chatting!", "text_fr": "Bon, bonne chance avec ça ! Je vois quelqu''un que je dois voir avant qu''il parte — super de discuter !", "choices": [{"text": "You too, enjoy the rest of the evening!", "text_fr": "Vous aussi, profitez du reste de la soirée !", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(You scan the room, spotting another interesting conversation opportunity nearby.)", "text_fr": "(Vous scannez la salle, repérant une autre opportunité de conversation intéressante à proximité.)", "choices": [{"text": "(Approach a small group discussing something animatedly.)", "text_fr": "(Approche-toi d''un petit groupe discutant avec animation.)", "next": "n5"}, {"text": "(Head toward the refreshment table where someone stands alone.)", "text_fr": "(Dirige-toi vers la table de rafraîchissements où quelqu''un se tient seul.)", "next": "n5b"}]}, "n5": {"speaker": "person2", "text": "(Notices you) Feel free to join! We were just discussing industry regulations.", "text_fr": "(Te remarque) N''hésitez pas à vous joindre ! On discutait justement des réglementations de l''industrie.", "choices": [{"text": "Thanks for including me! What''s the general consensus in the group?", "text_fr": "Merci de m''inclure ! Quel est le consensus général dans le groupe ?", "next": "n6"}]}, "n5b": {"speaker": "person3", "text": "Oh, hi! Trying to work up the courage to talk to more people tonight, honestly.", "text_fr": "Oh, salut ! J''essaie de trouver le courage de parler à plus de gens ce soir, honnêtement.", "choices": [{"text": "I totally understand, these events can feel overwhelming. What do you do?", "text_fr": "Je comprends totalement, ces événements peuvent sembler écrasants. Vous faites quoi ?", "next": "n6"}]}, "n6": {"speaker": "person2", "text": "Mixed opinions, honestly, but that''s what makes these conversations valuable.", "text_fr": "Des opinions partagées, honnêtement, mais c''est ce qui rend ces conversations précieuses.", "choices": [{"text": "Agreed, hearing different perspectives is exactly why I love these events.", "text_fr": "D''accord, entendre différentes perspectives c''est exactement pourquoi j''adore ces événements.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(After a lively group discussion, you''ve collected three new contacts and great insights.)", "text_fr": "(Après une discussion de groupe animée, vous avez collecté trois nouveaux contacts et de bonnes idées.)", "choices": [{"text": "(Reflect on the successful evening of networking as it winds down.)", "text_fr": "(Réfléchis sur la soirée de networking réussie alors qu''elle se termine.)", "next": "end_networked"}]}, "end_networked": {"speaker": "person2", "text": "This was a great conversation. Let''s definitely keep in touch after tonight!", "text_fr": "C''était une super conversation. Restons définitivement en contact après ce soir !", "end": true, "ending_label": "Soirée networking naviguée avec brio 🥂🌐"}}}'::jsonb, is_playable = true
where title = 'Naviguer une soirée networking avec plusieurs interlocuteurs'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
